import{_ as a,C as t,c as e,o as r,a0 as i,b as n,w as l,a as s,G as o,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Teamkommunikation","description":"","frontmatter":{},"headers":[],"relativePath":"sv/education/team-player/communication.md","filePath":"sv/education/team-player/communication.md"}');const m=a({name:"sv/education/team-player/communication.md"},[["render",function(a,u,m,k,g,h){const p=t("Mermaid");return r(),e("div",null,[u[1]||(u[1]=i('<h1 id="teamkommunikation" tabindex="-1">Teamkommunikation <a class="header-anchor" href="#teamkommunikation" aria-label="Permalink to &quot;Teamkommunikation&quot;">​</a></h1><p>Effektiv kommunikation är det som förvandlar en grupp individer till ett team. I boule, där strategin ständigt förändras och pressen är hög, kan hur du kommunicerar avgöra resultatet.</p><div class="tip custom-block"><p class="custom-block-title">Den stora idén</p><p><strong>Kommunikation är det som förvandlar individer till ett team.</strong> Tydlig, specifik och stödjande kommunikation under press skiljer bra team från fantastiska.</p></div><h2 id="kommunikationscykeln" tabindex="-1">Kommunikationscykeln <a class="header-anchor" href="#kommunikationscykeln" aria-label="Permalink to &quot;Kommunikationscykeln&quot;">​</a></h2><p>God teamkommunikation följer en cykel:</p>',5)),(r(),n(d,null,{default:l(()=>[o(p,{id:"mermaid-17",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BObservera%5D%20--%3E%20B%5BDela%5D%0A%20%20%20%20B%20--%3E%20C%5BDiskutera%5D%0A%20%20%20%20C%20--%3E%20D%5BBesluta%5D%0A%20%20%20%20D%20--%3E%20E%5BUtf%C3%B6ra%5D%0A%20%20%20%20E%20--%3E%20F%5BRecension%5D%0A%20%20%20%20F%20--%3E%20A%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23f3e5f5%0A"})]),fallback:l(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[2]||(u[2]=i('<table tabindex="0"><thead><tr><th>Steg</th><th>Handling</th><th>Exempel</th></tr></thead><tbody><tr><td><strong>Observera</strong></td><td>Lägg märke till vad som händer</td><td>Terräng, positioner, motståndare</td></tr><tr><td><strong>Dela</strong></td><td>Berätta för dina lagkamrater vad du ser</td><td>&quot;Marken sluttar därifrån&quot;</td></tr><tr><td><strong>Diskutera</strong></td><td>Utbytesperspektiv</td><td>&quot;Ska jag blockera eller satsa på poäng?&quot;</td></tr><tr><td><strong>Besluta</strong></td><td>Överens om tillvägagångssätt</td><td>&quot;Vi provar den höga lobben&quot;</td></tr><tr><td><strong>Utföra</strong></td><td>Gör det med engagemang</td><td>Fullt fokus på kastet</td></tr><tr><td><strong>Recension</strong></td><td>Lär dig av resultatet</td><td>&quot;Det fungerade bra&quot; eller &quot;Nästa gång...&quot;</td></tr></tbody></table><h2 id="nar-man-ska-kommunicera" tabindex="-1">När man ska kommunicera <a class="header-anchor" href="#nar-man-ska-kommunicera" aria-label="Permalink to &quot;När man ska kommunicera&quot;">​</a></h2><h3 id="fore-varje-slut" tabindex="-1">Före varje slut <a class="header-anchor" href="#fore-varje-slut" aria-label="Permalink to &quot;Före varje slut&quot;">​</a></h3><ul><li>Bedöm terrängen tillsammans</li><li>Diskutera den allmänna strategin</li><li>Förtydliga vem som kastar när</li><li>Sätt tonen (lugn, fokuserad)</li></ul><h3 id="under-slutet" tabindex="-1">Under slutet <a class="header-anchor" href="#under-slutet" aria-label="Permalink to &quot;Under slutet&quot;">​</a></h3><ul><li>Dela observationer (&quot;Marksluttningen som lämnas där&quot;)</li><li>Koordinationsstrategi (&quot;Ska jag försöka blockera eller gå för poängen?&quot;)</li><li>Erbjud stöd (&quot;Ta din tid, du klarar det här&quot;)</li><li>Anpassa planer när situationen förändras</li></ul><h3 id="mellan-andarna" tabindex="-1">Mellan ändarna <a class="header-anchor" href="#mellan-andarna" aria-label="Permalink to &quot;Mellan ändarna&quot;">​</a></h3><ul><li>Snabb genomgång (vad fungerade, vad fungerade inte)</li><li>Återställ mentalt</li><li>Förbered dig för nästa slut</li><li>Håll kontakten som ett team</li></ul><h3 id="efter-matchen" tabindex="-1">Efter matchen <a class="header-anchor" href="#efter-matchen" aria-label="Permalink to &quot;Efter matchen&quot;">​</a></h3><ul><li>Fullständig debriefing (vid behov)</li><li>Erkänn bidrag</li><li>Identifiera lärdomar</li><li>Upprätthåll relationen</li></ul><h2 id="hur-man-kommunicerar" tabindex="-1">Hur man kommunicerar <a class="header-anchor" href="#hur-man-kommunicerar" aria-label="Permalink to &quot;Hur man kommunicerar&quot;">​</a></h2><h3 id="var-tydlig-och-specifik" tabindex="-1">Var tydlig och specifik <a class="header-anchor" href="#var-tydlig-och-specifik" aria-label="Permalink to &quot;Var tydlig och specifik&quot;">​</a></h3><p><strong>Vagt:</strong> &quot;Försök att komma nära&quot; <strong>Klart:</strong> &quot;Sikta mot vänster sida av domkraften, cirka 20 cm ut&quot;</p><p><strong>Vagt:</strong> &quot;Bra försök&quot; <strong>Klart:</strong> &quot;Bra vikt, bara en liten bit kvar av linjen&quot;</p><h3 id="var-konstruktiv" tabindex="-1">Var konstruktiv <a class="header-anchor" href="#var-konstruktiv" aria-label="Permalink to &quot;Var konstruktiv&quot;">​</a></h3><p>Fokusera på lösningar, inte problem:</p><p><strong>Problemfokuserad:</strong> &quot;Du fortsätter att missa till höger&quot; <strong>Lösningsfokuserad:</strong> &quot;Kanske försöka sikta lite mer åt vänster för att kompensera?&quot;</p><h3 id="var-stodjande" tabindex="-1">Var stödjande <a class="header-anchor" href="#var-stodjande" aria-label="Permalink to &quot;Var stödjande&quot;">​</a></h3><p>Din ton är lika viktig som dina ord:</p><ul><li>Behåll lugnet, även när du är frustrerad</li><li>Använd uppmuntrande kroppsspråk</li><li>Erkänn ansträngningar, inte bara resultat</li><li>Bygg upp, riv inte ner</li></ul><h3 id="lyssna-aktivt" tabindex="-1">Lyssna aktivt <a class="header-anchor" href="#lyssna-aktivt" aria-label="Permalink to &quot;Lyssna aktivt&quot;">​</a></h3><p>Kommunikation är tvåvägs:</p><ul><li>Ge full uppmärksamhet när lagkamrater pratar</li><li>Ställ förtydligande frågor</li><li>Bekräfta vad du har hört</li><li>Avbryt inte eller avfärda</li></ul><h2 id="kommunikationsutmaningar" tabindex="-1">Kommunikationsutmaningar <a class="header-anchor" href="#kommunikationsutmaningar" aria-label="Permalink to &quot;Kommunikationsutmaningar&quot;">​</a></h2><h3 id="oenighet-om-strategi" tabindex="-1">Oenighet om strategi <a class="header-anchor" href="#oenighet-om-strategi" aria-label="Permalink to &quot;Oenighet om strategi&quot;">​</a></h3><p><strong>Dåligt tillvägagångssätt:</strong></p><ul><li>Insistera på din väg</li><li>Bli defensiv</li><li>Ge efter bittert</li><li>Bråka under spelets gång</li></ul><p><strong>Bättre tillvägagångssätt:</strong></p><ol><li>Dela ditt perspektiv tydligt</li><li>Lyssna på deras helt</li><li>Diskutera för- och nackdelar kortfattat</li><li>Besluta tillsammans (eller låt det gå till utsedd ledare)</li><li>Förbind dig helt och hållet till beslutet</li><li>Recension efter matchen</li></ol><h3 id="efter-en-lagkamrats-misstag" tabindex="-1">Efter en lagkamrats misstag <a class="header-anchor" href="#efter-en-lagkamrats-misstag" aria-label="Permalink to &quot;Efter en lagkamrats misstag&quot;">​</a></h3><p><strong>Vad de behöver:</strong></p><ul><li>Snabb bekräftelse</li><li>Tillstånd att gå vidare</li><li>Förtroendet att du fortfarande litar på dem</li><li>Fokusera på nästa kast</li></ul><p><strong>Vad ska man säga:</strong></p><ul><li>&quot;Inga problem, nästa&quot;</li><li>&quot;Tuff paus, du har nästa&quot;</li><li>&quot;Vi är fortfarande inne på det här&quot;</li><li><em>Ibland räcker det med en nick eller klapp</em></li></ul><p><strong>Vad man INTE ska säga:</strong></p><ul><li>Ingenting (tystnad känns som en dom)</li><li>&quot;Det är okej&quot; (kan låta avfärdande)</li><li>Något om vad som gick fel (inte nu)</li><li>Synlig frustration (kroppsspråk räknas)</li></ul><h3 id="nar-du-gor-ett-misstag" tabindex="-1">När du gör ett misstag <a class="header-anchor" href="#nar-du-gor-ett-misstag" aria-label="Permalink to &quot;När du gör ett misstag&quot;">​</a></h3><p><strong>Vad man ska göra:</strong></p><ul><li>Kort tack (&quot;Mitt fel&quot;)</li><li>Be inte om ursäkt för mycket</li><li>Hitta inte på ursäkter</li><li>Återställ och fokusera på nästa kast</li><li>Lita på att dina lagkamrater stöttar dig</li></ul><h3 id="spanningen-i-laget" tabindex="-1">Spänningen i laget <a class="header-anchor" href="#spanningen-i-laget" aria-label="Permalink to &quot;Spänningen i laget&quot;">​</a></h3><p>Om spänningen byggs upp under en match:</p><ol><li>Inse att det händer</li><li>Ta ett andetag innan du svarar</li><li>Fokusera på spelet, inte konflikten</li><li>Ta itu med det ordentligt efter matchen</li><li>Låt det inte påverka ditt spelande</li></ol><h2 id="icke-verbal-kommunikation" tabindex="-1">Icke-verbal kommunikation <a class="header-anchor" href="#icke-verbal-kommunikation" aria-label="Permalink to &quot;Icke-verbal kommunikation&quot;">​</a></h2><p>Mycket av teamets kommunikation är icke-verbal:</p><h3 id="positiva-signaler" tabindex="-1">Positiva signaler <a class="header-anchor" href="#positiva-signaler" aria-label="Permalink to &quot;Positiva signaler&quot;">​</a></h3><ul><li>Ögonkontakt</li><li>Nickar</li><li>Tummen upp</li><li>Avslappnad hållning</li><li>Rör sig mot lagkamrater</li><li>Leende (när det är lämpligt)</li></ul><h3 id="negativa-signaler-undvik-dessa" tabindex="-1">Negativa signaler (undvik dessa) <a class="header-anchor" href="#negativa-signaler-undvik-dessa" aria-label="Permalink to &quot;Negativa signaler (undvik dessa)&quot;">​</a></h3><ul><li>Ögonrullning</li><li>Vändande bort</li><li>Korsade armar</li><li>Suckande</li><li>Skakar på huvudet</li><li>Spänt kroppsspråk</li></ul><p><strong>Kom ihåg:</strong> Dina lagkamrater ser allt. Ditt kroppsspråk påverkar deras självförtroende och prestation.</p><h2 id="bygga-kommunikationsvanor" tabindex="-1">Bygga kommunikationsvanor <a class="header-anchor" href="#bygga-kommunikationsvanor" aria-label="Permalink to &quot;Bygga kommunikationsvanor&quot;">​</a></h2><h3 id="praktikkommunikation" tabindex="-1">Praktikkommunikation <a class="header-anchor" href="#praktikkommunikation" aria-label="Permalink to &quot;Praktikkommunikation&quot;">​</a></h3><p>Vänta inte på att konkurrenterna ska kommunicera:</p><ul><li>Öva strategiska diskussioner i utbildningen</li><li>Ge varandra feedback regelbundet</li><li>Utveckla ert lagspråk</li><li>Bygg trygghet med ärliga samtal</li></ul><h3 id="utveckla-teamsignaler" tabindex="-1">Utveckla teamsignaler <a class="header-anchor" href="#utveckla-teamsignaler" aria-label="Permalink to &quot;Utveckla teamsignaler&quot;">​</a></h3><p>Vissa team utvecklar förkortningar:</p><ul><li>Handsignaler för strategi</li><li>Kodord för situationer</li><li>Snabba fraser med gemensam betydelse</li></ul><h3 id="regelbundna-incheckningar" tabindex="-1">Regelbundna incheckningar <a class="header-anchor" href="#regelbundna-incheckningar" aria-label="Permalink to &quot;Regelbundna incheckningar&quot;">​</a></h3><p>Utanför spelen:</p><ul><li>Hur arbetar vi tillsammans?</li><li>Vad går bra?</li><li>Vad kan vara bättre?</li><li>Några problem att åtgärda?</li></ul><h2 id="kaptenens-roll" tabindex="-1">Kaptenens roll <a class="header-anchor" href="#kaptenens-roll" aria-label="Permalink to &quot;Kaptenens roll&quot;">​</a></h2><p>Om ert team har en utsedd ledare:</p><p><strong>Kaptenens ansvarsområden:</strong></p><ul><li>Slutgiltigt beslut när laget är oense</li><li>Sätter tonen och energin</li><li>Hantera teamdynamik</li><li>Att hålla fokus under press</li></ul><p><strong>Alla andra:</strong></p><ul><li>Dela ditt perspektiv</li><li>Stöd beslutet när det väl är fattat</li><li>Hjälp till att upprätthålla teamets energi</li><li>Ta ansvar för din roll</li></ul><h2 id="viktig-slutsats" tabindex="-1">Viktig slutsats <a class="header-anchor" href="#viktig-slutsats" aria-label="Permalink to &quot;Viktig slutsats&quot;">​</a></h2><blockquote><p>Bra team pratar med varandra, inte om varandra. De kommunicerar med ärlighet, respekt och ett gemensamt engagemang för framgång.</p></blockquote><p>Öva kommunikation på samma sätt som du övar på att kasta. Det är en färdighet som förbättras med uppmärksamhet.</p>',68))])}]]);export{u as __pageData,m as default};
